Here's an idiomatic worker pool implementation. It returns a results channel so callers can consume processed output, and it closes that channel once all workers finish.

```go
package main

import (
	"fmt"
	"sync"
	"time"
)

// process simulates work on a single job.
func process(id, job int) int {
	time.Sleep(100 * time.Millisecond) // simulate work
	fmt.Printf("worker %d processed job %d\n", id, job)
	return job * job
}

// WorkerPool spawns n goroutines that read from jobs until it is closed.
// It returns a channel of results, which is closed after all workers exit.
func WorkerPool(jobs <-chan int, n int) <-chan int {
	if n < 1 {
		n = 1
	}

	results := make(chan int)
	var wg sync.WaitGroup
	wg.Add(n)

	for i := 1; i <= n; i++ {
		go func(id int) {
			defer wg.Done()
			for job := range jobs { // exits when jobs is closed and drained
				results <- process(id, job)
			}
		}(i)
	}

	// Close results once every worker has finished.
	go func() {
		wg.Wait()
		close(results)
	}()

	return results
}

func main() {
	jobs := make(chan int)

	// Producer: send jobs, then close the channel to signal completion.
	go func() {
		defer close(jobs)
		for i := 1; i <= 10; i++ {
			jobs <- i
		}
	}()

	results := WorkerPool(jobs, 3)

	sum := 0
	for r := range results {
		sum += r
	}
