	"fmt"
	"sync"
	"time"
)

// process is the work done for each job. Replace with your own logic.
func process(job int) int {
	time.Sleep(100 * time.Millisecond) // simulate work
	return job * job
}

// WorkerPool spawns n goroutines that read from jobs until it is closed.
// It returns a channel of results, which is closed after all workers finish.
func WorkerPool(jobs <-chan int, n int) <-chan int {
	if n < 1 {
		n = 1
	}

	results := make(chan int)
	var wg sync.WaitGroup
	wg.Add(n)

	for i := 0; i < n; i++ {
		go func(id int) {
			defer wg.Done()
			for job := range jobs { // exits when jobs is closed and drained
				results <- process(job)
			}
		}(i)
	}

	// Close results once all workers are done, so consumers can range over it.
	go func() {
		wg.Wait()
		close(results)
	}()

	return results
}

