package main

import (
	"encoding/json"
	"fmt"
	"os"
)

// Config represents the application configuration loaded from a JSON file.
type Config struct {
	Name string `json:"name"`
	Port int    `json:"port"`
}

// LoadConfig reads a JSON file from disk and unmarshals it into a Config struct.
func LoadConfig(path string) (*Config, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("open config file %q: %w", path, err)
	}
	defer f.Close()

	var cfg Config
	dec := json.NewDecoder(f)
	dec.DisallowUnknownFields() // optional: fail on unexpected fields
	if err := dec.Decode(&cfg); err != nil {
		return nil, fmt.Errorf("decode config file %q: %w", path, err)
	}

	return &cfg, nil
}
