package main

import (
	"fmt"
	"sync"
)

// WorkerPool spawns n goroutines that consume jobs from the channel
// until it is closed. It blocks until all workers have finished.
func WorkerPool(jobs <-chan int, n int) {
	if n <= 0 {
		return
	}

	var wg sync.WaitGroup

	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(workerID int) {
			defer wg.Done()
			for job := range jobs {
				process(workerID, job)
			}
		}(i)
	}

	wg.Wait()
}

// process does the actual work for a single job.
func process(workerID, job int) {
	fmt.Printf("worker %d processed job %d\n", workerID, job)
}

func main() {
	jobs := make(chan int, 100)
	for i := 1; i <= 10; i++ {
		jobs <- i
	}
	close(jobs) // closing the channel signals the workers to exit

	WorkerPool(jobs, 3)
}
```

Key points:

- **`sync.WaitGroup`** ensures `WorkerPool` doesn't return until every worker goroutine has exited.
- **`for job := range jobs`** loops until the channel is closed, then the goroutine terminates.
- **The channel must be closed** by the producer, otherwise `WorkerPool` blocks forever.
- Replace `process` with your real work; if you need results, add a results channel (e.g. `results chan int`) and have workers send to it.

A variant that returns results:

```go
func WorkerPool(jobs <-chan int, n int) []int {
	var wg sync.WaitGroup
	var mu sync.Mutex
	results := make([]int, 0)

	for i := 0; i < n; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for job := range jobs {
				mu.Lock()
				results = append(results, job*2)
				mu.Unlock()
			}
		}()
	}

	wg.Wait()
	return results
}
```

