## Variant: with cancellation and panic safety

```go
func WorkerPoolCtx(ctx context.Context, jobs <-chan int, n int) {
	var wg sync.WaitGroup
	wg.Add(n)

	for i := 0; i < n; i++ {
		go func(id int) {
			defer wg.Done()
			defer func() {
				if r := recover(); r != nil {
					log.Printf("worker %d panicked: %v", id, r)
