import "sync"

// WorkerPool starts n goroutines that consume jobs from the channel
// until the channel is closed.
func WorkerPool(jobs <-chan int, n int) {
	if n < 1 {
		n = 1
	}

	var wg sync.WaitGroup
	wg.Add(n)

	for i := 0; i < n; i++ {
		go func() {
			defer wg.Done()
			for job := range jobs {
				process(job)
			}
		}()
	}

	wg.Wait()
}

// Replace with your actual processing logic.
func process(job int) {
	// do something with job
}
```

Each goroutine reads from `jobs` until it is closed, and `WorkerPool` returns only after all workers have finished. If you need the results, use a buffered results channel sized `n` so workers never block on sends:

```go
func WorkerPool(jobs <-chan int, n int) <-chan int {
	results := make(chan int, n)
	var wg sync.WaitGroup
	wg.Add(n)

	for i := 0; i < n; i++ {
		go func() {
			defer wg.Done()
			for job := range jobs {
				results <- process(job)
			}
		}()
	}

	go func() {
		wg.Wait()
		close(results)
	}()

	return results
}

func process(job int) int {
	return job * 2 // example
}
```

